#include <bits/stdc++.h>
using namespace std;
int main() {
    int m;
    cin >> m;
    vector<pair<long long, int>> ev;
    long long low = LLONG_MAX, high = LLONG_MIN;
    for (int g = 0; g < m; g++) {
        int k;
        cin >> k;
        vector<pair<long long, long long>> a;
        for (int j = 0; j < k / 2; j++) {
            long long x, y;
            cin >> x >> y;
            if (x > y)
                swap(x, y);
            low = min(low, x);
            high = max(high, y);
            a.push_back({x, y});
        }
        sort(a.begin(), a.end());
        long long l = -1, r = -1;
        for (auto [x, y] : a) {
            if (l < 0) {
                l = x;
                r = y;
            } else if (x <= r)
                r = max(r, y);
            else {
                if (l < r) {
                    ev.push_back({l, 1});
                    ev.push_back({r, -1});
                }
                l = x;
                r = y;
            }
        }
        if (l >= 0 && l < r) {
            ev.push_back({l, 1});
            ev.push_back({r, -1});
        }
    }
    sort(ev.begin(), ev.end());
    vector<long long> len(m + 1);
    long long prev = low;
    int active = 0;
    for (auto [x, d] : ev) {
        len[active] += x - prev;
        active += d;
        prev = x;
    }
    len[active] += high - prev;
    vector<int> ord(m + 1);
    iota(ord.begin(), ord.end(), 0);
    sort(ord.begin(), ord.end(),
         [&](int a, int b) { return len[a] != len[b] ? len[a] > len[b] : a < b; });
    for (int j = 0; j < 2; j++)
        cout << ord[j] << ' ' << fixed << setprecision(2)
             << 100.L * len[ord[j]] / (high - low) << "%\n";
}

