        string w;
        while (in >> w) {
            if (!cnt[k].count(w))
                order[k].push_back(w);
            cnt[k][w]++;
            total[w]++;
        }
    }
    map<int, vector<string>, greater<int>> groups[2];
    for (int k = 0; k < 2; k++)
        for (string w : order[k])
            groups[k][total[w]].push_back(w);
    set<int, greater<int>> freq;
    for (auto [w, f] : total)
        freq.insert(f);
    set<string> chosen;
    vector<string> axes;
    for (int f : freq) {
        auto &a = groups[0][f], &b = groups[1][f];
        size_t pos[2] = {};
        int turn = 0;
        while (pos[0] < a.size() || pos[1] < b.size()) {
            auto &v = turn ? b : a;
            while (pos[turn] < v.size() && chosen.count(v[pos[turn]]))
                pos[turn]++;
            if (pos[turn] < v.size()) {
                string w = v[pos[turn]++];
                chosen.insert(w);
                axes.push_back(w);
                if ((int)axes.size() == N)
                    break;
            }
            turn ^= 1;
        }
        if ((int)axes.size() == N)
            break;
    }
    long double dot = 0, A = 0, B = 0;
    for (string w : axes) {
        long double a = cnt[0][w], b = cnt[1][w];
        dot += a * b;
        A += a * a;
        B += b * b;
    }
    cout << fixed << setprecision(2) << (A && B ? dot / sqrtl(A * B) : 0) << '\n';
}

