#include <bits/stdc++.h>
using namespace std;
#include <boost/multiprecision/cpp_int.hpp>
using boost::multiprecision::cpp_int;
cpp_int gcdBig(cpp_int a, cpp_int b) {
    while (b != 0) {
        cpp_int r = a % b;
        a = b;
        b = r;
    }
    return a;
}
int main() {
    string tok;
    cin >> tok;
    int T = stoi(tok);
    while (T--) {
        do {
            cin >> tok;
        } while (tok == "/" || tok == ".");
        int n = stoi(tok);
        vector<int> c(n), p(n), rem(n), deadline(n), done(n);
        cpp_int num = 0, den = 1;
        int maxP = 0;
        for (int i = 0; i < n; i++) {
            cin >> c[i] >> p[i];
            num = num * p[i] + den * c[i];
            den *= p[i];
            cpp_int g = gcdBig(num, den);
            num /= g;
            den /= g;
            maxP = max(maxP, p[i]);
        }
        if (num > den) {
            cout << 0 << '\n';
            continue;
        }
        int current = -1, finished = 0, ans = 0;
        for (int t = 0; t < maxP; t++) {
            for (int i = 0; i < n; i++)
                if (t % p[i] == 0) {
                    rem[i] = c[i];
                    deadline[i] = t + p[i];
                }
            int best = -1;
            for (int i = 0; i < n; i++)
                if (rem[i] &&
                    (best < 0 ||
                     make_tuple(deadline[i], -rem[i], i == current ? 0 : 1, i) <
                         make_tuple(deadline[best], -rem[best], best == current ? 0 : 1,
                                    best)))
                    best = i;
            current = best;
            if (best >= 0 && !--rem[best] && !done[best]) {
                done[best] = 1;
                finished++;
            }
            if (finished == n) {
                ans = t + 1;
                break;
            }
        }
        cout << ans << '\n';
    }
}

