#include <bits/stdc++.h>
using namespace std;
struct DSU {
    vector<int> p, s;
    int parts;
    DSU(int n) : p(n), s(n, 1), parts(n) {
        iota(p.begin(), p.end(), 0);
    }
    int find(int x) {
        while (x != p[x])
            x = p[x] = p[p[x]];
        return x;
    }
    bool join(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b)
            return 0;
        if (s[a] < s[b])
            swap(a, b);
        p[b] = a;
        s[a] += s[b];
        parts--;
        return 1;
    }
};
struct E {
    int u, v, l, r;
    long long w;
};
int main() {
    int n, m, d;
    cin >> n >> m >> d;
    vector<E> e(m);
    for (auto &x : e) {
        cin >> x.u >> x.v >> x.w >> x.l >> x.r;
        --x.u;
        --x.v;
    }
    stable_sort(e.begin(), e.end(), [](E a, E b) { return a.w < b.w; });
    vector<long long> ans(d, -1);
    function<void(int, vector<E>, int, int, long long)> solve =
        [&](int N, vector<E> es, int L, int R, long long base) {
            if (N == 1) {
                fill(ans.begin() + L, ans.begin() + R, base);
                return;
            }
            if ((int)es.size() < N - 1)
                return;
            vector<int> fixed, var;
            for (int i = 0; i < (int)es.size(); i++)
                (es[i].l <= L && R <= es[i].r ? fixed : var).push_back(i);
            if (var.empty()) {
                DSU z(N);
                long long cost = base;
                for (auto x : es)
                    if (z.join(x.u, x.v))
                        cost += x.w;
                if (z.parts == 1)
                    fill(ans.begin() + L, ans.begin() + R, cost);
                return;
            }
            DSU temp(N);
            for (int i : var)
                temp.join(es[i].u, es[i].v);
            vector<int> must;
            for (int i : fixed)
                if (temp.join(es[i].u, es[i].v))
                    must.push_back(i);
            if (temp.parts > 1)
                return;
            DSU z(N);
            for (int i : must) {
                z.join(es[i].u, es[i].v);
                base += es[i].w;
            }
            vector<int> id(N, -1);
            int M = 0;
            for (int i = 0; i < N; i++)
                if (z.find(i) == i)
                    id[i] = M++;
            DSU reduced(M);
            vector<E> keep;
            for (auto x : es) {
                x.u = id[z.find(x.u)];
                x.v = id[z.find(x.v)];
                if (x.u == x.v)
                    continue;
                if (x.l <= L && R <= x.r) {
                    if (reduced.join(x.u, x.v))
                        keep.push_back(x);
                } else
                    keep.push_back(x);
            }
            int mid = (L + R) / 2;
            vector<E> a, b;
            for (auto x : keep) {
                if (x.l < mid && x.r > L)
                    a.push_back(x);
                if (x.l < R && x.r > mid)
                    b.push_back(x);
            }
            solve(M, move(a), L, mid, base);
            solve(M, move(b), mid, R, base);
        };
    solve(n, e, 0, d, 0);
    for (int i = 0; i < d; i++) {
        if (i)
            cout << ' ';
        cout << ans[i];
    }
    cout << '\n';
}

