        self.sz = [1] * n
        self.parts = n

    def find(self, x):
        p = self.p
        while x != p[x]:
            p[x] = p[p[x]]
            x = p[x]
        return x

    def join(self, a, b):
        a, b = self.find(a), self.find(b)
        if a == b:
            return False
        if self.sz[a] < self.sz[b]:
            a, b = b, a
        self.p[b] = a
        self.sz[a] += self.sz[b]
        self.parts -= 1
        return True


def solve(N, es, L, R, base):
