struct Close {
    long long d;
    int a, b;
};
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, K;
    cin >> n >> K;
    vector<Pt> p(n);
    for (auto &a : p)
        cin >> a.x >> a.y;
    auto sq = [&](int a, int b) {
        long long x = p[a].x - p[b].x, y = p[a].y - p[b].y;
        return x * x + y * y;
    };
    auto dist = [&](int a, int b) { return sqrt((double)sq(a, b)); };
    vector<int> sorted(n);
    iota(sorted.begin(), sorted.end(), 0);
    sort(sorted.begin(), sorted.end(),
         [&](int a, int b) { return tie(p[a].x, p[a].y) < tie(p[b].x, p[b].y); });
    auto closest = [&](vector<int> ids) {
        function<Close(int, int)> rec = [&](int l, int r) {
            Close ans{LLONG_MAX, -1, -1};
            if (r - l <= 3) {
                for (int i = l; i < r; i++)
                    for (int j = i + 1; j < r; j++) {
                        long long d = sq(ids[i], ids[j]);
                        if (d < ans.d)
                            ans = {d, ids[i], ids[j]};
                    }
                sort(ids.begin() + l, ids.begin() + r,
                     [&](int a, int b) { return p[a].y < p[b].y; });
                return ans;
            }
            int m = (l + r) / 2;
            long long x = p[ids[m]].x;
            auto A = rec(l, m), B = rec(m, r);
            ans = A.d < B.d ? A : B;
            inplace_merge(ids.begin() + l, ids.begin() + m, ids.begin() + r,
                          [&](int a, int b) { return p[a].y < p[b].y; });
            vector<int> s;
            for (int i = l; i < r; i++) {
                int u = ids[i];
                long long dx = p[u].x - x;
                if (dx * dx >= ans.d)
                    continue;
                for (int j = (int)s.size() - 1; j >= 0; j--) {
                    long long dy = p[u].y - p[s[j]].y;
                    if (dy * dy >= ans.d)
                        break;
                    long long d = sq(u, s[j]);
                    if (d < ans.d)
                        ans = {d, u, s[j]};
                }
                s.push_back(u);
            }
            return ans;
        };
        return rec(0, ids.size());
    };
    vector<pair<int, int>> matching;
    double total = 0, global = 0;
    for (int round = 0; round < K; round++) {
        vector<char> used(n);
        for (auto [a, b] : matching)
            used[a] = used[b] = 1;
        vector<int> free;
        for (int u : sorted)
            if (!used[u])
                free.push_back(u);
        auto direct = closest(free);
        double directCost = sqrt((double)direct.d);
        if (round == 0)
            global = directCost;
        if (round == 0 || total + directCost <= (round + 1) * global + 1e-10) {
            matching.push_back({direct.a, direct.b});
            total += directCost;
            continue;
        }
        int r = matching.size(), V = 2 * r;
        vector<int> end;
        vector<double> len(r);
        for (int j = 0; j < r; j++) {
            end.push_back(matching[j].first);
            end.push_back(matching[j].second);
            len[j] = dist(end[2 * j], end[2 * j + 1]);
        }
        vector<vector<pair<int, double>>> near(V);
        vector<int> pool;
        for (int t = 0; t < V; t++) {
            pair<long long, int> a = {LLONG_MAX, -1}, b = a;
            for (int u : free) {
                pair<long long, int> z = {sq(end[t], u), u};
                if (z < a) {
                    b = a;
                    a = z;
                } else if (z < b)
                    b = z;
            }
            for (auto z : {a, b})
                if (z.second >= 0) {
                    auto it = find(pool.begin(), pool.end(), z.second);
                    int id = it == pool.end() ? pool.size() : it - pool.begin();
                    if (it == pool.end())
                        pool.push_back(z.second);
                    near[t].push_back({id, sqrt((double)z.first)});
                }
        }
        vector<vector<double>> D(V, vector<double>(V));
        for (int i = 0; i < V; i++)
            for (int j = 0; j < V; j++)
                D[i][j] = dist(end[i], end[j]);
        int states = 1 << r;
        size_t size = (size_t)states * V * 2;
        vector<double> dp(size, numeric_limits<double>::infinity());
        vector<unsigned char> origin(size, 255), prev(size, 255);
        auto insert = [&](size_t base, double value, int src, int parent) {
            if (origin[base] == src) {
                if (value < dp[base]) {
                    dp[base] = value;
                    prev[base] = parent;
                }
                return;
            }
            if (origin[base + 1] == src) {
                if (value >= dp[base + 1])
                    return;
                dp[base + 1] = value;
                prev[base + 1] = parent;
                if (dp[base + 1] < dp[base]) {
                    swap(dp[base], dp[base + 1]);
                    swap(origin[base], origin[base + 1]);
                    swap(prev[base], prev[base + 1]);
                }
                return;
            }
            if (value < dp[base]) {
                dp[base + 1] = dp[base];
                origin[base + 1] = origin[base];
                prev[base + 1] = prev[base];
                dp[base] = value;
                origin[base] = src;
                prev[base] = parent;
            } else if (value < dp[base + 1]) {
                dp[base + 1] = value;
                origin[base + 1] = src;
                prev[base + 1] = parent;
            }
        };
        for (int a = 0; a < V; a++)
            for (auto [src, d] : near[a])
                insert(((size_t)(1 << (a / 2)) * V + (a ^ 1)) * 2, d - len[a / 2], src,
                       255);
        double best = directCost;
        int bm = 0, bt = 0, bs = 0, finish = -1;
        for (int mask = 1; mask < states; mask++) {
            int bits = mask;
            while (bits) {
                int j = __builtin_ctz((unsigned)bits);
                bits &= bits - 1;
                for (int t : {2 * j, 2 * j + 1})
                    for (int slot = 0; slot < 2; slot++) {
                        size_t at = ((size_t)mask * V + t) * 2 + slot;
                        if (origin[at] == 255)
                            continue;
                        double value = dp[at];
                        int src = origin[at];
                        for (auto [dest, d] : near[t])
                            if (dest != src && value + d < best) {
                                best = value + d;
                                bm = mask;
                                bt = t;
                                bs = slot;
                                finish = dest;
                            }
                        int left = (states - 1) ^ mask;
                        while (left) {
                            int h = __builtin_ctz((unsigned)left);
                            left &= left - 1;
                            int next = mask | (1 << h);
                            for (int a : {2 * h, 2 * h + 1})
                                insert(((size_t)next * V + (a ^ 1)) * 2,
                                       value + D[t][a] - len[h], src, t * 2 + slot);
                        }
                    }
            }
        }
        if (!bm)
            matching.push_back({direct.a, direct.b});
        else {
            vector<int> path = {pool[finish], end[bt]};
            int mask = bm, t = bt, slot = bs;
            while (mask) {
                size_t at = ((size_t)mask * V + t) * 2 + slot;
                path.push_back(end[t ^ 1]);
                int par = prev[at], src = origin[at];
                mask ^= 1 << (t / 2);
                if (par == 255) {
                    path.push_back(pool[src]);
                    break;
                }
                t = par / 2;
                slot = par % 2;
                path.push_back(end[t]);
            }
            vector<pair<int, int>> next;
            for (int j = 0; j < r; j++)
                if (!(bm >> j & 1))
                    next.push_back(matching[j]);
            for (int i = 0; i + 1 < (int)path.size(); i += 2)
                next.push_back({path[i], path[i + 1]});
            matching.swap(next);
        }
        total = 0;
        for (auto [a, b] : matching)
            total += dist(a, b);
    }
    cout << fixed << setprecision(10) << total << '\n';
