int diameter() {
    int n;
    cin >> n;
    int W = (n + 63) / 64;
    vector<vector<unsigned long long>> g(n, vector<unsigned long long>(W));
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++) {
            char c;
            cin >> c;
            if (c == '1')
                g[i][j / 64] |= 1ULL << (j % 64);
        }
    int ans = 0;
    for (int s = 0; s < n; s++) {
        vector<unsigned long long> seen(W), front(W);
        seen[s / 64] = front[s / 64] = 1ULL << (s % 64);
        int count = 1, dist = 0;
        while (1) {
            vector<unsigned long long> next(W);
            for (int b = 0; b < W; b++) {
                auto z = front[b];
                while (z) {
                    int u = b * 64 + __builtin_ctzll(z);
                    z &= z - 1;
                    for (int k = 0; k < W; k++)
                        next[k] |= g[u][k];
                }
            }
            int add = 0;
            for (int k = 0; k < W; k++) {
                next[k] &= ~seen[k];
                add += __builtin_popcountll(next[k]);
                seen[k] |= next[k];
            }
            if (!add)
                break;
            count += add;
            dist++;
            front.swap(next);
        }
        if (count < n)
            return -1;
        ans = max(ans, dist);
    }
    return ans;
}
